package com.primehr.migration;import org.flywaydb.core.Flyway;import org.flywaydb.core.api.MigrationVersion;import org.junit.jupiter.api.Test;import java.sql.DriverManager;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PrimeHrV28ToV29UpgradeTest{@Test void populatedObjectiveSurvivesCommitmentCompositionMigration()throws Exception{String db="primehr_v29_"+UUID.randomUUID().toString().replace("-","");String url="jdbc:h2:mem:"+db+";MODE=PostgreSQL;DB_CLOSE_DELAY=-1";Map<String,String> placeholders=Map.of("primehrSchema","PUBLIC");Flyway initial=Flyway.configure().dataSource(url,"sa","").locations("classpath:db/migration/postgresql").schemas("PUBLIC").defaultSchema("PUBLIC").placeholders(placeholders).target(MigrationVersion.fromVersion("28")).cleanDisabled(false).load();initial.migrate();String id=UUID.randomUUID().toString();try(var connection=DriverManager.getConnection(url,"sa","")){connection.createStatement().executeUpdate("INSERT INTO PUBLIC.spms_objective (id,agency_id,code,normalized_code,record_version,created_by,created_at,updated_by,updated_at) VALUES ('"+id+"','UPGRADE-29','OBJ','OBJ',0,'test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");}try{Flyway upgraded=Flyway.configure().dataSource(url,"sa","").locations("classpath:db/migration/postgresql").schemas("PUBLIC").defaultSchema("PUBLIC").placeholders(placeholders).target(MigrationVersion.fromVersion("29")).cleanDisabled(false).load();upgraded.migrate();assertThat(upgraded.info().current().getVersion().getVersion()).isEqualTo("29");try(var connection=DriverManager.getConnection(url,"sa","");var result=connection.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.spms_objective WHERE id='"+id+"'")){result.next();assertThat(result.getLong(1)).isOne();for(String table:List.of("spms_commitment","spms_commitment_version","spms_commitment_section","spms_commitment_item","spms_commitment_cascade")){try(var empty=connection.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC."+table)){empty.next();assertThat(empty.getLong(1)).isZero();}}}}finally{initial.clean();}}}
